package com.fitconnect.notification.service; import com.fitconnect.notification.api.*; import com.fitconnect.notification.domain.*; import com.fitconnect.notification.repository.NotificationRepository; import org.slf4j.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class NotificationService {private static final Logger LOG=LoggerFactory.getLogger(NotificationService.class);private final NotificationRepository repo;public NotificationService(NotificationRepository repo){this.repo=repo;}@Transactional public NotificationResponse create(NotificationRequest r){Notification n=repo.save(new Notification(r.userId(),r.email(),r.type(),r.subject(),r.content()));n.send();LOG.info("notification sent to {}: {}",n.getEmail(),n.getSubject());return NotificationResponse.from(repo.save(n));}public List<NotificationResponse> user(Long id){return repo.findByUserId(id).stream().map(NotificationResponse::from).toList();}public List<NotificationResponse> pending(){return repo.findByStatus(NotificationStatus.PENDING).stream().map(NotificationResponse::from).toList();}@Transactional public NotificationResponse retry(Long id){Notification n=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Notification introuvable"));n.send();return NotificationResponse.from(repo.save(n));}}
